#!/bin/sh
# Generates machine-local pubspec_overrides.yaml files that resolve
# `unseal` from the sibling Unseal checkout, mirroring the local stack
# layout:
#
#   <parent>/unseal
#   <parent>/grimoire   <- this repository
#
# The generated file is gitignored on purpose: the committed contract stays
# on the hosted `unseal: ^1.0.0` constraint in pubspec.yaml, and the
# multi-repo CI integration lane runs this same script in-job.
#
# Usage: tool/generate_local_overrides.sh
set -eu

root="$(cd "$(dirname "$0")/.." && pwd)"

if [ ! -d "$root/../unseal" ]; then
  echo "error: sibling Unseal checkout not found at $root/../unseal" >&2
  echo "       clone https://github.com/KaiqueFarias09/unseal next to this" >&2
  echo "       repository, or let CI's integration lane do it for you" >&2
  exit 1
fi

write_override() {
  # $1 = target file, $2 = path to the Unseal checkout
  {
    printf '# Generated by tool/generate_local_overrides.sh. Machine-local, do not commit.\n'
    printf 'dependency_overrides:\n'
    printf '  unseal:\n    path: %s\n' "$2"
  } > "$1"
}

write_override "$root/pubspec_overrides.yaml" "../unseal"
write_override "$root/example/pubspec_overrides.yaml" "../../unseal"

echo "generated $root/pubspec_overrides.yaml and $root/example/pubspec_overrides.yaml"
